      visitDefinitionListEnd: (ctx, text) async => VisitResult.continue_(),
      visitForm: (ctx, action, method) async => VisitResult.continue_(),
      visitInput: (ctx, inputType, name, value) async => VisitResult.continue_(),
      visitButton: (ctx, text) async => VisitResult.continue_(),
      visitAudio: (ctx, src) async => VisitResult.continue_(),
      visitVideo: (ctx, src) async => VisitResult.continue_(),
      visitIframe: (ctx, src) async => VisitResult.continue_(),
      visitDetails: (ctx, open) async => VisitResult.continue_(),
      visitSummary: (ctx, text) async => VisitResult.continue_(),
      visitFigureStart: (ctx) async => VisitResult.continue_(),
      visitFigcaption: (ctx, text) async => VisitResult.continue_(),
      visitFigureEnd: (ctx, output) async => VisitResult.continue_()
    );
    final options = await createConversionOptionsFromJsonWithVisitor(visitor: visitor, json: '{}');
    final result = await H2mBridge.convert('<article><p>Article text</p><x-custom>Custom element with content</x-custom><p>More article text</p></article>', options: options);
    expect(result.content, contains('Article text'));
    expect(result.content, contains('More article text'));
    expect(result.content, contains('<x-custom>'));
    expect(result.content, isNot(contains('preserve_html')));
  });

  test('Whitespace-only content', () async {
    final options = await createConversionOptionsFromJson(json: '{}');
    final result = await H2mBridge.convert('<p>   </p>', options: options);
    expect(result.content.toString(), equals(''.toString()));
  });

  test('onclick and other on* event handlers are removed from elements', () async {
    final options = await createConversionOptionsFromJson(json: '{}');
    final result = await H2mBridge.convert('<p><a href="https://example.com" onclick="alert(\'xss\')">Click me</a></p><button onmouseover="steal_data()">Hover me</button>', options: options);
    expect(result.content?.toString(), isNotEmpty);
    expect(result.content, contains('Click me'));
    expect(result.content, isNot(contains('onclick')));
    expect(result.content, isNot(contains('onmouseover')));
    expect(result.content, isNot(contains('alert(')));
    expect(result.content, isNot(contains('steal_data')));
  });

  test('Script tag content is stripped and does not appear in output', () async {
    final options = await createConversionOptionsFromJson(json: '{}');
    final result = await H2mBridge.convert('<p>Safe content.</p><script>alert(\'xss\')</script><p>More safe content.</p>', options: options);
    expect(result.content?.toString(), isNotEmpty);
    expect(result.content, contains('Safe content'));
    expect(result.content, contains('More safe content'));
    expect(result.content, isNot(contains('<script>')));
    expect(result.content, isNot(contains('alert(')));
    expect(result.content, isNot(contains('xss')));
  });

  test('Script tags nested inside SVG are stripped', () async {
    final options = await createConversionOptionsFromJson(json: '{}');
    final result = await H2mBridge.convert('<p>Before SVG.</p><svg xmlns="http://www.w3.org/2000/svg"><script>alert(\'svg-xss\')</script><text>SVG text</text></svg><p>After SVG.</p>', options: options);
    expect(result.content?.toString(), isNotEmpty);
    expect(result.content, contains('Before SVG'));
    expect(result.content, contains('After SVG'));
    expect(result.content, isNot(contains('<script>')));
    expect(result.content, isNot(contains('alert(')));
    expect(result.content, isNot(contains('svg-xss')));
  });

}
